"""Adjusts the metrion.yaml (≥ 0.2) written by `metrion init` for joule:code.

Call it with metrion's own Python (which comes with pyyaml), see scripts/install.sh:

    python configure_v2.py metrion.yaml [--no-dram] [--keep-raw]

The starting point is always the default configuration of the installed metrion version;
only the keys below are changed – that way the script stays valid across versions.
"""

from __future__ import annotations

import argparse
from pathlib import Path

import yaml

HEADER = """\
# metrion configuration for joule:code – generated by scripts/install.sh from `metrion init`.
# Changed compared with the default configuration: debug off, Parquet, live attribution on,
# GPU and network off (joule:code measures CPU programs; the GTX 1080 has no
# energy counter). Commented version: `metrion init` in an empty directory.
"""


def main() -> None:
    p = argparse.ArgumentParser()
    p.add_argument("config", type=Path)
    p.add_argument("--no-dram", action="store_true", help="no RAPL DRAM domain available")
    p.add_argument("--keep-raw", action="store_true", help="additionally store raw data")
    args = p.parse_args()

    cfg = yaml.safe_load(args.config.read_text())
    cfg["debug"] = False
    storage = cfg.setdefault("storage", {})
    storage["type"] = "parquet"
    storage["path"] = "./monitor"
    # Without raw data metrion only writes the live result – orders of magnitude smaller,
    # and there is no write backlog on shutdown.
    storage["store_raw_measurements"] = bool(args.keep_raw)
    live = cfg.setdefault("live_attribution", {})
    live["enabled"] = True
    live.setdefault("path", "./energy")
    components = cfg.setdefault("energy_model", {}).setdefault("components", {})
    off = ["gpu", "network"] + (["dram"] if args.no_dram else [])
    for name in off:
        if name in components:
            components[name]["mode"] = "exclude"
    args.config.write_text(HEADER + yaml.safe_dump(cfg, sort_keys=False, allow_unicode=True))
    print(f"{args.config}: " + ", ".join(f"{n} off" for n in off))


if __name__ == "__main__":
    main()
